import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

const STATUS_LABELS: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  archived: 'В архиве',
};

const STATUS_TONES: Record<ProjectStatus, 'success' | 'warning' | 'default'> = {
  active: 'success',
  paused: 'warning',
  archived: 'default',
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'archived'];

const PAGE_SIZE = 5;

const PROJECTS: Project[] = [
  { id: 'atlas', name: 'Атлас', used: 8200, quota: 10000, status: 'active' },
  { id: 'beacon', name: 'Маяк', used: 4300, quota: 12000, status: 'paused' },
  { id: 'context', name: 'Контекст', used: 9600, quota: 10000, status: 'active' },
  { id: 'delta', name: 'Дельта', used: 1500, quota: 6000, status: 'archived' },
  { id: 'echo', name: 'Эхо', used: 5400, quota: 9000, status: 'active' },
  { id: 'forge', name: 'Кузница', used: 7100, quota: 8000, status: 'paused' },
  { id: 'grove', name: 'Роща', used: 300, quota: 5000, status: 'archived' },
  { id: 'harbor', name: 'Гавань', used: 6650, quota: 7000, status: 'active' },
  { id: 'iris', name: 'Ирис', used: 2400, quota: 8000, status: 'active' },
  { id: 'juno', name: 'Юнона', used: 3300, quota: 4000, status: 'paused' },
  { id: 'kite', name: 'Змей', used: 900, quota: 3000, status: 'archived' },
  { id: 'lumen', name: 'Люмен', used: 5800, quota: 6500, status: 'active' },
];

export default function ProjectQuotaPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(STATUS_ORDER);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(STATUS_ORDER);
    setPage(1);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUS_ORDER.map((status) => (
          <JxChip
            key={status}
            active={statuses.includes(status)}
            removable={statuses.includes(status)}
            onRemove={() => toggleStatus(status)}
            onClick={() => toggleStatus(status)}
          >
            {STATUS_LABELS[status]}
          </JxChip>
        ))}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Проектов не нашлось"
          message="Ни один проект не подходит под выбранные статусы."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'grid',
                  gridTemplateColumns: '1fr auto auto',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 16px',
                  background: 'var(--jx-surface)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <span style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}>
                  {project.name}
                </span>
                <JxProgressCircle value={project.used} max={project.quota} showValue />
                <JxBadge tone={STATUS_TONES[project.status]} dot>
                  {STATUS_LABELS[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

